CREATE FUNCTION public.fn_sp_digest_player_period(date) RETURNS jsonb LANGUAGE sql AS $$SELECT '{"totals":{"net":226.47,"cash_net":590.72,"tournament_net":-364.25},"players":[{"user_id":"00000000-0000-0000-0001-000000000001","username":"winner","net":500},{"user_id":"00000000-0000-0000-0001-000000000002","username":"loser","net":-273.53}],"period":{"day":{},"week":{},"month":{}}}'::jsonb$$;
